#!/bin/bash
# Exercise the shared validator and the installed-hook entry point without commits.
set -euo pipefail
repo_dir=$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)
cd "$repo_dir"
message_file=$(mktemp)
trap 'rm -f "$message_file"' EXIT
checks=0

# Two package scopes of this repository; the shared cases below use them so
# that no case depends on another repository's package names.
scope_a=http/client
scope_b=urlx
for scope in "$scope_a" "$scope_b" deps README docs devtools ci; do
    if ! awk '!/^[[:space:]]*#/ && NF {print $1}' commit_scopes.txt | grep -Fxq -- "$scope"; then
        printf 'Scope %s used by these checks is missing from commit_scopes.txt\n' "$scope" >&2
        exit 1
    fi
done

check() {
    local expected=$1 message=$2 entry actual
    printf '%s\n' "$message" > "$message_file"
    for entry in .github/scripts/validate-commit-message.sh .githooks/commit-msg; do
        actual=0
        if [[ "$entry" == .githooks/commit-msg ]]; then
            bash "$entry" "$message_file" >/dev/null 2>&1 || actual=$?
        else
            bash "$entry" < "$message_file" >/dev/null 2>&1 || actual=$?
        fi
        if [[ "$actual" != "$expected" ]]; then
            printf 'Unexpected status %s (wanted %s) from %s: %s\n' "$actual" "$expected" "$entry" "$message" >&2
            exit 1
        fi
        checks=$((checks + 1))
    done
}

# Format, types and scopes.
check 0 "fix($scope_a): preserve provider usage"
check 0 'build: pin the options generator'
check 0 "feat($scope_b)!: reject recursive definitions"
check 0 'refactor!: remove the legacy entry point'
check 0 "fix($scope_a): preserve provider usage"$'\n\nKeep usage when a paid reply contains an error.'
check 0 "feat($scope_b)!: reject recursion"$'\n\nBREAKING CHANGE: recursive definitions now fail before dispatch.'
check 0 "fix($scope_a): preserve provider usage"$'\n\nCo-authored-by: Jane Doe <jane@example.com>'
check 0 'ci: enforce the coverage floor'
check 0 'revert: restore endpoint validation'
check 0 'build(devtools): bump golangci-lint'
check 0 'docs(README): describe the quick start'
check 0 'docs(docs): link the architecture notes'
check 1 'fix(root): update configuration'
check 1 'build(deps): '
check 1 'fix(unknown): update configuration'
check 1 "Fix($scope_a): preserve provider usage"
check 1 "fix($scope_a): Preserve provider usage"
check 1 'update configuration'
check 1 'fix(): update configuration'
check 1 'Revert "fix: restore endpoint validation"'

# Only real scope lines of commit_scopes.txt count: comment and blank lines,
# and the words of a comment, name no scope.
check 1 'fix(#): update configuration'
check 1 'fix(# Packages): update configuration'
check 1 'fix(Packages): update configuration'
check 1 'fix(Tooling): update configuration'

# Dependabot messages (build(deps) via .github/dependabot.yml) pass the normal
# rules without an exemption, and their bodies are checked like any other.
check 0 'build(deps): bump golang.org/x/sys from 0.1.0 to 0.2.0'
check 0 'build(deps): bump actions/checkout from 4.4.0 to 5.0.0'
check 0 'build(deps): bump golang.org/x/sys from 0.1.0 to 0.2.0 in /devtools'
check 0 $'build(deps): bump golang.org/x/sys from 0.1.0 to 0.2.0\n\nBumps golang.org/x/sys from 0.1.0 to 0.2.0.\n\nSigned-off-by: dependabot[bot] <support@github.com>'
check 1 'build(deps): Bump golang.org/x/sys from 0.1.0 to 0.2.0'
check 1 $'build(deps): bump golang.org/x/sys from 0.1.0 to 0.2.0\n\nGenerated by Claude Code'

# Merge subjects: only the ones git generates are exempt; the body is checked.
check 0 "Merge branch 'release/v0.1.3'"
check 0 "Merge tag 'v0.1.3' into develop"
check 0 'Merge pull request #12 from altessa-s/feature/x'
check 1 'Merge branch develop'
check 1 'Merge the release'
check 1 $'Merge branch \'develop\'\n\nGenerated with Claude Code'

# Reports.
check 1 "fix($scope_a): preserve provider usage"$'\n\nTests: go test ./... passed'
check 1 "fix($scope_a): preserve provider usage"$'\n\nCoverage: 95%'
check 1 "fix($scope_a): preserve provider usage"$'\n\nAll tests passed'

# Agent attribution and agent co-author trailers.
check 1 "fix($scope_a): preserve provider usage"$'\n\nGenerated with Claude Code'
check 1 "fix($scope_a): preserve provider usage"$'\n\nGenerated by an AI assistant.'
check 1 "fix($scope_a): preserve provider usage"$'\n\nWritten with the help of ChatGPT.'
check 1 "fix($scope_a): preserve provider usage"$'\n\nimplemented using an LLM'
check 1 $'build(devtools): update the generator\n\nCo-authored-by: Codex <codex@example.com>'
check 1 "fix($scope_a): preserve provider usage"$'\n\nCo-authored-by: Claude <noreply@anthropic.com>'
check 1 "fix($scope_a): preserve provider usage"$'\n\nCo-authored-by: Copilot <175728472+Copilot@users.noreply.github.com>'
check 1 "fix($scope_a): preserve provider usage"$'\n\nAgent: Codex'

# Agent names match as whole words only: ordinary words that contain "ai" or
# "agent" are not attribution, and human co-authors named like "bot" are fine.
check 0 "fix($scope_a): keep the delay"$'\n\nThe schedule created by NewPolicy is retained across attempts.'
check 0 "fix($scope_a): keep the detail"$'\n\nThe detail written by the maintained writer is kept.'
check 0 "fix($scope_b): keep the agents list"$'\n\nThe list created by the reagent loader stays sorted.'
check 0 "fix($scope_a): preserve provider usage"$'\n\nCo-authored-by: Abbot Robotham <abbot@example.com>'
check 0 "fix($scope_a): preserve provider usage"$'\n\nCo-authored-by: Maida Rain <maida@example.com>'
printf 'Passed %s commit validation checks\n' "$checks"
